var fs = require('fs');
var path = require('path');

var buffer1 = Buffer.from('Node.js buffers are powerful');

buffer1.write('FAST ', 0, 5);

var buffer2 = Buffer.from(' and flexible!');

var finalBuffer = Buffer.concat([buffer1, buffer2]);

var finalText = finalBuffer.toString();

var filePath = path.join(__dirname, 'buffer_output.txt');

fs.writeFileSync(filePath, finalText);

console.log('File saved at: ' + filePath);